/* Scoped preflight for copied components. No selectors affect the host page. */
@import "./ui-base.css";
:where(.roc-shadcn, .roc-shadcn *, .roc-shadcn::before, .roc-shadcn::after) {
  box-sizing: border-box;
  border-width: 0;
  border-style: solid;
  border-color: var(--roc-line, #e5e5e5);
}
:where(.roc-shadcn) {
  font-family: inherit;
  line-height: 1.5;
  color: var(--roc-ink, #252525);
  /* One place maps the ROC design tokens (ink, paper, line, muted, marker, focus, accent, radius)
     onto the shadcn-named variables every copied component reads. */
  --roc-sh-radius-xs: max(0px, calc(var(--roc-radius-control) - 6px));
  --roc-sh-radius-sm: max(0px, calc(var(--roc-radius-control) - 4px));
  --roc-sh-radius-md: var(--roc-radius-control);
  --roc-sh-radius-lg: var(--roc-radius-surface);
  --roc-sh-radius-xl: min(24px, calc(var(--roc-radius-surface) * 1.25));
  --roc-sh-color-background: var(--roc-paper, #fff);
  --roc-sh-color-foreground: var(--roc-ink, #252525);
  --roc-sh-color-card: var(--roc-paper, #fff);
  --roc-sh-color-card-foreground: var(--roc-ink, #252525);
  --roc-sh-color-popover: var(--roc-paper, #fff);
  --roc-sh-color-popover-foreground: var(--roc-ink, #252525);
  --roc-sh-color-muted: color-mix(in srgb, var(--roc-ink, #252525) 4%, var(--roc-paper, #fff));
  --roc-sh-color-muted-foreground: var(--roc-muted, #737373);
  --roc-sh-color-accent: var(--roc-marker, #f3f3f3);
  --roc-sh-color-accent-foreground: var(--roc-ink, #252525);
  --roc-sh-color-secondary: var(--roc-marker, #f3f3f3);
  --roc-sh-color-secondary-foreground: var(--roc-ink, #252525);
  --roc-sh-color-border: var(--roc-line, #e5e5e5);
  --roc-sh-color-input: var(--roc-line, #dedede);
  --roc-sh-color-ring: var(--roc-focus, #737373);
  --roc-sh-color-primary: var(--roc-accent, var(--roc-ink, #252525));
  --roc-sh-color-primary-foreground: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
:where(
  button.roc-shadcn,
  input.roc-shadcn,
  select.roc-shadcn,
  textarea.roc-shadcn
) {
  font: inherit;
  color: inherit;
  background: transparent;
}
:where(button.roc-shadcn) {
  cursor: pointer;
}
:where(button.roc-shadcn:disabled) {
  cursor: not-allowed;
}
:where(
  .roc-shadcn h1,
  .roc-shadcn h2,
  .roc-shadcn h3,
  .roc-shadcn p,
  .roc-shadcn pre,
  h1.roc-shadcn,
  h2.roc-shadcn,
  h3.roc-shadcn,
  p.roc-shadcn,
  pre.roc-shadcn
) {
  margin: 0;
}
:where(ul.roc-shadcn, ol.roc-shadcn) {
  list-style: none;
  margin: 0;
  padding: 0;
}
:where(.roc-shadcn svg) {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
:where(.roc-shadcn input) {
  min-width: 0;
}
/* Menu rows sit 4px inside their surface, so their curves share a center. */
.roc-shadcn:is(
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"],
  [data-slot="select-content"]
) {
  border-radius: var(--roc-radius-popup);
}
.roc-shadcn:is(
  [data-slot="context-menu-item"],
  [data-slot="context-menu-checkbox-item"],
  [data-slot="context-menu-radio-item"],
  [data-slot="context-menu-sub-trigger"],
  [data-slot="menubar-item"],
  [data-slot="menubar-checkbox-item"],
  [data-slot="menubar-radio-item"],
  [data-slot="menubar-sub-trigger"],
  [data-slot="select-item"]
) {
  border-radius: max(0px, calc(var(--roc-radius-popup) - 4px));
}
@media (prefers-reduced-motion: reduce) {
  .roc-shadcn,
  .roc-shadcn * {
    scroll-behavior: auto !important;
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

.roc-shadcn[hidden],
.roc-shadcn [hidden] {
  display: none !important;
}
